<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class logs extends lib { public function __construct() { add_filter( 'qqworld-collector-settings-nav-tabs', array($this, 'add_nav_tab') ); add_action( 'qqworld-collector-settings-nav-sections', array($this, 'add_nav_section') ); add_action( 'wp_ajax_qqworld-collector-settings-delete-log', array($this, 'delete_log') ); add_action( 'wp_ajax_nopriv_qqworld-collector-settings-delete-log', array($this, 'delete_log') ); add_action( 'qqworld-collector-log', array($this, 'log'), 10, 4 ); } public function init() {} public function add_nav_tab($nav_tabs) { $nav_tabs['debug'] = __('Debug', $this->text_domain); return $nav_tabs; } public function add_nav_section() { global $blog_id; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'settings-logs.php'; } public function delete_log() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; extract($_POST); $path = stripslashes($path); if (file_exists($path)) { unlink($path); $results = array( 'success' => 1, 'msg' => sprintf(__('Successfully deleted the log file:<br /><em>%s</em>', $this->text_domain), $path) ); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function log($guid, $title, $content, $force=false) { global $blog_id; if ($force || filter_var($this->options->qc_debug_enabled, FILTER_VALIDATE_BOOLEAN)) { $log_path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'logs'; if (!is_dir($log_path)) mkdir($log_path); $log_path .= DIRECTORY_SEPARATOR . $blog_id; if (!is_dir($log_path)) mkdir($log_path); $log_path .= DIRECTORY_SEPARATOR . 'qqworld-collector'; if (!is_dir($log_path)) mkdir($log_path); $log_path .= DIRECTORY_SEPARATOR . $guid . '.log'; $time = date(get_option('date_format') . ' @ H:i:s', current_time('timestamp') ); $log = $time . ' - ' . $title . "\n" . $content . "\n=============================================================================================================================\n\n"; error_log($log, 3, $log_path); } } } ?>